proguardAdditions.insert:

-keep class com.taptap.sdk.leaderboard.** { *; }
-keep interface com.taptap.sdk.leaderboard.** { *; }

-keep class com.taptap.sdk.leaderboard.internal.ue.** { *; }
-keepclassmembers class com.taptap.sdk.leaderboard.internal.ue.** { *; }

-keep @android.support.annotation.Keep class * { *; }
-keep @androidx.annotation.Keep class * { *; }

-keepclasseswithmembernames class * {
    native <methods>;
}

-keepattributes *Annotation*
-keepattributes Signature
-keepattributes Exceptions
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile

-keep class com.taptap.sdk.kit.internal.enginebridge.** { *; }

gameActivityClassAdditions.insert:

// The Android SDK keeps this callback in a SoftReference. GameActivity must retain
// it so image sharing can still report its result after a garbage collection.
private ITapTapLeaderboardShareCallback tapLeaderboardShareCallback;

public String routeToTapLeaderboard(String requestJson, EngineBridgeCallback callback) {
    try {
        String result = TapLeaderboardUERouter.route(this, requestJson, callback);
        if ("setShareCallback".equals(new org.json.JSONObject(requestJson).optString("method"))) {
            tapLeaderboardShareCallback = TapTapLeaderboard.getShareCallback();
        }
        return result;
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapLeaderboard route error: " + e.getMessage(), e);
        return "{\"success\":false,\"message\":\"" + e.getMessage() + "\"}";
    }
}
